output_text:
[
  {
    "id": "must_get_cart",
    "text": "The shopper is obliged to have a cart at some point before completing the trip.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_cart_upper_aisle",
    "text": "The shopper is prohibited from having a cart in the upper aisle cells at (6,1) or (6,2).",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          {
            "or": [
              "at(6,1)",
              "at(6,2)"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_at_6_1",
    "text": "The shopper is prohibited from bringing a cart to cell (6,1).",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "at(6,1)"
        ]
      }
    }
  },
  {
    "id": "drop_cart_after_interact_6_3",
    "text": "If the shopper interacts at (6,3) while holding a cart, they are obliged to stop having the cart afterward.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(6,3)",
          "hasCart",
          "INTERACT"
        ]
      },
      "discharge": {
        "not": "hasCart"
      }
    }
  },
  {
    "id": "retrieve_cart_at_6_3",
    "text": "If the shopper interacts at (6,3) without a cart, they are obliged to have the cart afterward.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(6,3)",
          {
            "not": "hasCart"
          },
          "INTERACT"
        ]
      },
      "discharge": "hasCart"
    }
  },
  {
    "id": "must_return_to_cart_after_6_1",
    "text": "After interacting at (6,1), the shopper is obliged to have a cart again later.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(6,1)",
          "INTERACT"
        ]
      },
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "The shopper is prohibited from exiting the store without a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_west_movement",
    "text": "The shopper is prohibited from moving west in the store.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": "W"
    }
  }
]
